class Solution {
  private int[] ones;
  private long enc, flat;

  private long cost(int l, int r) {
    int len = r - l;
    int x = ones[r] - ones[l];
    long whole = x == 0 ? flat : (long) len * x * enc;
    if (len % 2 == 0 && len > 1) {
      int mid = l + len / 2;
      whole = Math.min(whole, cost(l, mid) + cost(mid, r));
    }
    return whole;
  }

  public long minCost(String s, int encCost, int flatCost) {
    int n = s.length();
    ones = new int[n + 1];
    for (int i = 0; i < n; i++) ones[i + 1] = ones[i] + (s.charAt(i) == '1' ? 1 : 0);
    enc = encCost;
    flat = flatCost;
    return cost(0, n);
  }
}
